private void xrTableCell12_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {

string Text1 = GetCurrentColumnValue("PERSHKRIMI").ToString();
if(!String.IsNullOrEmpty(Text1) && Text1.Length > 15)
{ xrTableCell12.Text = Text1.Substring(0, 15) + "..."; }
}
